Brief:
A paper kite rides the wind over the rooftops. Tap to rise, avoid the chimneys and collect ribbons while the wind slowly speeds up.

Plan:
{"gameType":"arcade-run","input":"tap-anywhere","lang":"en","loop":"Tap to make your paper kite rise on the wind, dodge the chimneys, and collect ribbons as the breeze quickens. One crash into a chimney ends the flight.","slug":"kite-above-the-rooftops","style":"paper-cut","title":"Kite Above the Rooftops"}

Game source (line-numbered):
1| <!doctype html>
2| <html lang="en">
3| <head>
4| <meta charset="utf-8">
5| <meta name="viewport" content="width=device-width, initial-scale=1">
6| <title>Kite Above the Rooftops</title>
7| <style>
8|   html, body {
9|     margin: 0; padding: 0; width: 100%; height: 100%;
10|     background: #f4ecd8;
11|     overflow: hidden;
12|     font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif;
13|   }
14|   canvas {
15|     display: block;
16|     touch-action: none;
17|   }
18| </style>
19| </head>
20| <body>
21| <canvas id="game"></canvas>
22| <script>
23| // ---- Bridge helper (verbatim) ----
24| const CARTRIDGE = {
25|   send(type, payload = {}) {
26|     window.parent.postMessage(
27|       { source: "cartridge", v: 1, type, payload },
28|       "*",
29|     );
30|   },
31| };
32| 
33| // ---- Setup ----
34| const canvas = document.getElementById("game");
35| const ctx = canvas.getContext("2d");
36| canvas.style.touchAction = "none";
37| 
38| let DPR = Math.max(1, window.devicePixelRatio || 1);
39| let W = 0, H = 0;
40| 
41| function resize() {
42|   W = window.innerWidth;
43|   H = window.innerHeight;
44|   canvas.width = Math.floor(W * DPR);
45|   canvas.height = Math.floor(H * DPR);
46|   canvas.style.width = W + "px";
47|   canvas.style.height = H + "px";
48|   ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
49| }
50| window.addEventListener("resize", resize);
51| resize();
52| 
53| // ---- Palette ----
54| const COLORS = {
55|   bg: "#f4ecd8",
56|   layer: "#e07a5f",
57|   accent: "#3d405b",
58|   highlight: "#81b29a",
59| };
60| 
61| // ---- Seeded jitter helper ----
62| function makeJitterSeed(n) {
63|   const arr = [];
64|   let s = n * 9301 + 49297;
65|   for (let i = 0; i < 40; i++) {
66|     s = (s * 9301 + 49297) % 233280;
67|     arr.push((s / 233280) * 2 - 1);
68|   }
69|   return arr;
70| }
71| const jitterTable = makeJitterSeed(777);
72| function jit(i, amt) {
73|   return jitterTable[i % jitterTable.length] * amt;
74| }
75| 
76| // ---- Rounded rect path with jitter ----
77| function jitterRoundRect(x, y, w, h, r, seedBase) {
78|   ctx.beginPath();
79|   const pts = [
80|     [x + r, y],
81|     [x + w - r, y],
82|     [x + w, y + r],
83|     [x + w, y + h - r],
84|     [x + w - r, y + h],
85|     [x + r, y + h],
86|     [x, y + h - r],
87|     [x, y + r],
88|   ];
89|   // simple jittered rounded rect approximation using arcs at corners
90|   ctx.beginPath();
91|   ctx.moveTo(x + r + jit(seedBase, 1.2), y + jit(seedBase + 1, 1.2));
92|   ctx.lineTo(x + w - r + jit(seedBase + 2, 1.2), y + jit(seedBase + 3, 1.2));
93|   ctx.quadraticCurveTo(x + w, y, x + w, y + r);
94|   ctx.lineTo(x + w + jit(seedBase + 4, 1.2), y + h - r + jit(seedBase + 5, 1.2));
95|   ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
96|   ctx.lineTo(x + r + jit(seedBase + 6, 1.2), y + h + jit(seedBase + 7, 1.2));
97|   ctx.quadraticCurveTo(x, y + h, x, y + h - r);
98|   ctx.lineTo(x + jit(seedBase + 8, 1.2), y + r + jit(seedBase + 9, 1.2));
99|   ctx.quadraticCurveTo(x, y, x + r, y);
100|   ctx.closePath();
101| }
102| 
103| function drawShadowLayer(drawFn) {
104|   ctx.save();
105|   ctx.shadowColor = "rgba(61,64,91,0.35)";
106|   ctx.shadowBlur = 6;
107|   ctx.shadowOffsetY = 3;
108|   drawFn();
109|   ctx.restore();
110| }
111| 
112| // ---- Game state ----
113| let last = 0;
114| let running = false;
115| let paused = false;
116| let started = false; // has boot happened
117| let score = 0;
118| let ribbons = 0;
119| let elapsed = 0;
120| let speed = 140; // px/s base scroll speed
121| let level = 1;
122| 
123| const kite = {
124|   x: 0,
125|   y: 0,
126|   vy: 0,
127|   radius: 18,
128|   angle: 0,
129| };
130| 
131| let chimneys = []; // {x, gapY, gapH, w, passed}
132| let ribbonsList = []; // {x, y, r, taken}
133| let clouds = [];
134| 
135| const GRAVITY = 480;
136| const LIFT = -320;
137| const CHIMNEY_GAP_MIN = 170;
138| const CHIMNEY_GAP_MAX = 230;
139| const CHIMNEY_W = 70;
140| let spawnTimer = 0;
141| let spawnInterval = 1.7;
142| 
143| function resetState() {
144|   score = 0;
145|   ribbons = 0;
146|   elapsed = 0;
147|   speed = 140;
148|   level = 1;
149|   kite.x = Math.max(90, W * 0.22);
150|   kite.y = H * 0.4;
151|   kite.vy = 0;
152|   kite.angle = 0;
153|   chimneys = [];
154|   ribbonsList = [];
155|   spawnTimer = 0;
156|   spawnInterval = 1.7;
157|   // fairness: clear opening lane, first hazard well ahead
158|   spawnTimer = -2.0;
159|   initClouds();
160| }
161| 
162| function initClouds() {
163|   clouds = [];
164|   for (let i = 0; i < 6; i++) {
165|     clouds.push({
166|       x: Math.random() * (W || 400),
167|       y: 40 + Math.random() * ((H || 600) * 0.4),
168|       r: 20 + Math.random() * 30,
169|       speed: 10 + Math.random() * 15,
170|     });
171|   }
172| }
173| 
174| let booted = false;
175| let gameOver = false;
176| 
177| function backToTitle() {
178|   running = false;
179|   paused = false;
180|   gameOver = false;
181|   resetState();
182| }
183| 
184| resetState();
185| 
186| // ---- Input ----
187| canvas.addEventListener("pointerdown", (event) => {
188|   event.preventDefault();
189|   if (paused) return;
190|   if (!started) {
191|     started = true;
192|   }
193|   if (!running) {
194|     if (gameOver) {
195|       resetState();
196|       gameOver = false;
197|     }
198|     running = true;
199|     CARTRIDGE.send("start");
200|     return;
201|   }
202|   act();
203| });
204| 
205| function act() {
206|   kite.vy = LIFT;
207| }
208| 
209| // ---- Host messages ----
210| window.addEventListener("message", (event) => {
211|   const data = event.data;
212|   if (!data || data.source !== "cartridge-host") return;
213|   if (data.type === "pause") paused = true;
214|   if (data.type === "resume") paused = false;
215|   if (data.type === "reset") backToTitle();
216| });
217| 
218| // ---- Spawning ----
219| function spawnChimney() {
220|   const gapH = CHIMNEY_GAP_MAX - Math.min(60, elapsed * 1.5) ;
221|   const gap = Math.max(CHIMNEY_GAP_MIN, gapH);
222|   const margin = 60;
223|   const gapY = margin + Math.random() * (H - margin * 2 - gap);
224|   chimneys.push({
225|     x: W + CHIMNEY_W,
226|     gapY: gapY,
227|     gapH: gap,
228|     w: CHIMNEY_W,
229|     passed: false,
230|     seed: Math.floor(Math.random() * 1000),
231|   });
232|   // maybe spawn a ribbon in the gap
233|   if (Math.random() < 0.8) {
234|     ribbonsList.push({
235|       x: W + CHIMNEY_W + 40,
236|       y: gapY + gap / 2,
237|       r: 12,
238|       taken: false,
239|     });
240|   }
241| }
242| 
243| // ---- Update ----
244| function advance(dt) {
245|   elapsed += dt;
246|   // difficulty ramp
247|   speed = 140 + Math.min(180, elapsed * 6);
248|   spawnInterval = Math.max(1.0, 1.7 - elapsed * 0.01);
249| 
250|   // level tracking (speed based, but we cannot emit 'level' per arcade-run - forbidden)
251|   // NOTE: arcade-run forbids level events, so we do not send them.
252| 
253|   kite.vy += GRAVITY * dt;
254|   kite.y += kite.vy * dt;
255|   kite.angle = Math.max(-0.5, Math.min(0.9, kite.vy / 500));
256| 
257|   if (kite.y < kite.radius) {
258|     kite.y = kite.radius;
259|     kite.vy = 0;
260|   }
261|   if (kite.y > H - kite.radius) {
262|     kite.y = H - kite.radius;
263|     crash();
264|     return;
265|   }
266| 
267|   spawnTimer += dt;
268|   if (spawnTimer >= spawnInterval) {
269|     spawnTimer = 0;
270|     spawnChimney();
271|   }
272| 
273|   for (let c of chimneys) {
274|     c.x -= speed * dt;
275|     if (!c.passed && c.x + c.w < kite.x) {
276|       c.passed = true;
277|       score += 1;
278|       CARTRIDGE.send("score", { value: score });
279|     }
280|   }
281|   chimneys = chimneys.filter((c) => c.x > -c.w - 10);
282| 
283|   for (let r of ribbonsList) {
284|     r.x -= speed * dt;
285|   }
286|   ribbonsList = ribbonsList.filter((r) => r.x > -30 && !r.taken);
287| 
288|   for (let cl of clouds) {
289|     cl.x -= cl.speed * dt;
290|     if (cl.x < -60) {
291|       cl.x = W + 60;
292|       cl.y = 30 + Math.random() * (H * 0.4);
293|     }
294|   }
295| }
296| 
297| function collide() {
298|   // chimneys
299|   for (let c of chimneys) {
300|     const kx = kite.x, ky = kite.y, kr = kite.radius * 0.75;
301|     const withinX = kx + kr > c.x && kx - kr < c.x + c.w;
302|     if (withinX) {
303|       const topH = c.gapY;
304|       const bottomY = c.gapY + c.gapH;
305|       if (ky - kr < topH || ky + kr > bottomY) {
306|         crash();
307|         return;
308|       }
309|     }
310|   }
311|   // ribbons
312|   for (let r of ribbonsList) {
313|     if (r.taken) continue;
314|     const dx = kite.x - r.x;
315|     const dy = kite.y - r.y;
316|     const dist = Math.sqrt(dx * dx + dy * dy);
317|     if (dist < kite.radius + r.r) {
318|       r.taken = true;
319|       ribbons += 1;
320|       score += 3;
321|       CARTRIDGE.send("score", { value: score });
322|     }
323|   }
324| }
325| 
326| function crash() {
327|   if (!running) return;
328|   running = false;
329|   gameOver = true;
330|   CARTRIDGE.send("end", { reason: "lose", value: score });
331| }
332| 
333| // ---- Drawing ----
334| function drawBackground() {
335|   ctx.fillStyle = COLORS.bg;
336|   ctx.fillRect(0, 0, W, H);
337| 
338|   // clouds - simple paper puffs, always moving for idle liveliness
339|   for (let cl of clouds) {
340|     drawShadowLayer(() => {
341|       ctx.fillStyle = "#ffffff";
342|       ctx.globalAlpha = 0.7;
343|       ctx.beginPath();
344|       ctx.ellipse(cl.x, cl.y, cl.r, cl.r * 0.6, 0, 0, Math.PI * 2);
345|       ctx.fill();
346|       ctx.globalAlpha = 1;
347|     });
348|   }
349| 
350|   // ground strip of rooftops silhouette
351|   drawShadowLayer(() => {
352|     ctx.fillStyle = COLORS.accent;
353|     ctx.globalAlpha = 0.15;
354|     ctx.fillRect(0, H - 14, W, 14);
355|     ctx.globalAlpha = 1;
356|   });
357| }
358| 
359| function drawChimney(c) {
360|   const topH = c.gapY;
361|   const bottomY = c.gapY + c.gapH;
362|   const bottomH = H - bottomY;
363| 
364|   drawShadowLayer(() => {
365|     ctx.fillStyle = COLORS.layer;
366|     jitterRoundRect(c.x, 0, c.w, topH, 6, c.seed);
367|     ctx.fill();
368|   });
369|   drawShadowLayer(() => {
370|     ctx.fillStyle = COLORS.layer;
371|     jitterRoundRect(c.x, bottomY, c.w, bottomH, 6, c.seed + 10);
372|     ctx.fill();
373|   });
374| 
375|   // accent cap bands
376|   ctx.fillStyle = COLORS.accent;
377|   ctx.globalAlpha = 0.85;
378|   ctx.fillRect(c.x - 2, Math.max(0, topH - 10), c.w + 4, 8);
379|   ctx.fillRect(c.x - 2, bottomY + 2, c.w + 4, 8);
380|   ctx.globalAlpha = 1;
381| }
382| 
383| function drawRibbon(r) {
384|   drawShadowLayer(() => {
385|     ctx.fillStyle = COLORS.highlight;
386|     ctx.beginPath();
387|     for (let i = 0; i < 8; i++) {
388|       const ang = (i / 8) * Math.PI * 2;
389|       const rad = r.r + jit(i + Math.floor(r.x), 1.5);
390|       const px = r.x + Math.cos(ang) * rad;
391|       const py = r.y + Math.sin(ang) * rad;
392|       if (i === 0) ctx.moveTo(px, py);
393|       else ctx.lineTo(px, py);
394|     }
395|     ctx.closePath();
396|     ctx.fill();
397|   });
398|   // little tail
399|   ctx.strokeStyle = COLORS.highlight;
400|   ctx.lineWidth = 3;
401|   ctx.beginPath();
402|   ctx.moveTo(r.x - r.r, r.y);
403|   ctx.lineTo(r.x - r.r - 14, r.y + 8);
404|   ctx.stroke();
405| }
406| 
407| function drawKite() {
408|   ctx.save();
409|   ctx.translate(kite.x, kite.y);
410|   ctx.rotate(kite.angle * 0.3);
411| 
412|   // tail
413|   ctx.strokeStyle = COLORS.accent;
414|   ctx.lineWidth = 2;
415|   ctx.beginPath();
416|   ctx.moveTo(-kite.radius * 0.6, kite.radius * 0.3);
417|   let px = -kite.radius * 0.6, py = kite.radius * 0.3;
418|   for (let i = 1; i <= 4; i++) {
419|     const nx = px - 10;
420|     const ny = py + (i % 2 === 0 ? -6 : 6);
421|     ctx.lineTo(nx, ny);
422|     px = nx; py = ny;
423|   }
424|   ctx.stroke();
425| 
426|   // kite body: diamond shape, paper-cut layered
427|   drawShadowLayer(() => {
428|     ctx.fillStyle = COLORS.layer;
429|     ctx.beginPath();
430|     const s = kite.radius * 1.4;
431|     ctx.moveTo(0 + jit(1, 1), -s + jit(2, 1));
432|     ctx.lineTo(s * 0.75 + jit(3, 1), 0 + jit(4, 1));
433|     ctx.lineTo(0 + jit(5, 1), s + jit(6, 1));
434|     ctx.lineTo(-s * 0.75 + jit(7, 1), 0 + jit(8, 1));
435|     ctx.closePath();
436|     ctx.fill();
437|   });
438| 
439|   // inner accent diamond
440|   ctx.fillStyle = COLORS.accent;
441|   ctx.globalAlpha = 0.5;
442|   ctx.beginPath();
443|   const s2 = kite.radius * 0.6;
444|   ctx.moveTo(0, -s2);
445|   ctx.lineTo(s2 * 0.75, 0);
446|   ctx.lineTo(0, s2);
447|   ctx.lineTo(-s2 * 0.75, 0);
448|   ctx.closePath();
449|   ctx.fill();
450|   ctx.globalAlpha = 1;
451| 
452|   ctx.restore();
453| }
454| 
455| function drawHUD() {
456|   // score plate
457|   drawShadowLayer(() => {
458|     ctx.fillStyle = "#ffffff";
459|     jitterRoundRect(14, 14, 130, 46, 10, 500);
460|     ctx.fill();
461|   });
462|   ctx.fillStyle = COLORS.accent;
463|   ctx.font = "bold 22px sans-serif";
464|   ctx.textBaseline = "middle";
465|   ctx.fillText("Score " + score, 28, 37);
466| }
467| 
468| function drawTitleScreen() {
469|   drawBackground();
470|   drawKite();
471| 
472|   drawShadowLayer(() => {
473|     ctx.fillStyle = "#ffffff";
474|     const w = Math.min(360, W - 40);
475|     jitterRoundRect(W / 2 - w / 2, H / 2 - 90, w, 150, 14, 200);
476|     ctx.fill();
477|   });
478| 
479|   ctx.fillStyle = COLORS.accent;
480|   ctx.textAlign = "center";
481|   ctx.font = "bold 26px sans-serif";
482|   ctx.fillText("Kite Above the Rooftops", W / 2, H / 2 - 40);
483| 
484|   const pulse = 0.6 + 0.4 * Math.sin(elapsed * 4);
485|   ctx.globalAlpha = pulse;
486|   ctx.font = "bold 20px sans-serif";
487|   ctx.fillStyle = COLORS.layer;
488|   ctx.fillText("Tap to begin", W / 2, H / 2 + 10);
489|   ctx.globalAlpha = 1;
490| 
491|   ctx.font = "16px sans-serif";
492|   ctx.fillStyle = COLORS.accent;
493|   ctx.fillText("Tap to rise, dodge chimneys, catch ribbons", W / 2, H / 2 + 45);
494|   ctx.textAlign = "left";
495| }
496| 
497| function drawGameOverScreen() {
498|   drawShadowLayer(() => {
499|     ctx.fillStyle = "#ffffff";
500|     const w = Math.min(320, W - 40);
501|     jitterRoundRect(W / 2 - w / 2, H / 2 - 80, w, 160, 14, 300);
502|     ctx.fill();
503|   });
504|   ctx.fillStyle = COLORS.accent;
505|   ctx.textAlign = "center";
506|   ctx.font = "bold 26px sans-serif";
507|   ctx.fillText("Crashed!", W / 2, H / 2 - 30);
508|   ctx.font = "bold 20px sans-serif";
509|   ctx.fillText("Score: " + score, W / 2, H / 2 + 6);
510|   const pulse = 0.6 + 0.4 * Math.sin(elapsed * 4);
511|   ctx.globalAlpha = pulse;
512|   ctx.font = "18px sans-serif";
513|   ctx.fillStyle = COLORS.layer;
514|   ctx.fillText("Tap to fly again", W / 2, H / 2 + 44);
515|   ctx.globalAlpha = 1;
516|   ctx.textAlign = "left";
517| }
518| 
519| function drawPauseOverlay() {
520|   ctx.fillStyle = "rgba(61,64,91,0.4)";
521|   ctx.fillRect(0, 0, W, H);
522|   ctx.fillStyle = "#ffffff";
523|   ctx.textAlign = "center";
524|   ctx.font = "bold 24px sans-serif";
525|   ctx.fillText("Paused", W / 2, H / 2);
526|   ctx.textAlign = "left";
527| }
528| 
529| function draw() {
530|   drawBackground();
531| 
532|   if (!started || (!running && !gameOver)) {
533|     drawTitleScreen();
534|   } else if (running) {
535|     for (let c of chimneys) drawChimney(c);
536|     for (let r of ribbonsList) if (!r.taken) drawRibbon(r);
537|     drawKite();
538|     drawHUD();
539|   } else if (gameOver) {
540|     for (let c of chimneys) drawChimney(c);
541|     for (let r of ribbonsList) if (!r.taken) drawRibbon(r);
542|     drawKite();
543|     drawHUD();
544|     drawGameOverScreen();
545|   }
546| 
547|   if (paused) {
548|     drawPauseOverlay();
549|   }
550| }
551| 
552| // ---- Main loop ----
553| function frame(now) {
554|   const dt = Math.min((now - last) / 1000, 0.05);
555|   last = now;
556| 
557|   if (running && !paused) {
558|     advance(dt || 0.016);
559|     collide();
560|   } else if (!running && !gameOver) {
561|     // idle clouds keep moving for liveliness
562|     elapsed += dt || 0.016;
563|     for (let cl of clouds) {
564|       cl.x -= cl.speed * (dt || 0.016);
565|       if (cl.x < -60) {
566|         cl.x = W + 60;
567|         cl.y = 30 + Math.random() * (H * 0.4);
568|       }
569|     }
570|   } else if (gameOver && !paused) {
571|     elapsed += dt || 0.016;
572|   }
573| 
574|   draw();
575|   requestAnimationFrame(frame);
576| }
577| 
578| requestAnimationFrame((t) => {
579|   last = t;
580|   draw();
581|   CARTRIDGE.send("boot", { title: "Kite Above the Rooftops", gameType: "arcade-run", lang: "en" });
582|   requestAnimationFrame(frame);
583| });
584| </script>
585| </body>
586| </html>
